    tmp = flb_output_get_property("data_mode", ins);
    if (tmp) {
        ctx->data_mode_str = flb_sds_create(tmp);
    }
    else {
        ctx->data_mode_str = flb_sds_create(FLB_DATA_MODE_STR_SINGLE_RECORD);
    }

    if (ctx->data_mode_str != NULL &&
        strcasecmp(ctx->data_mode_str, FLB_DATA_MODE_STR_CHUNK) == 0) {
        ctx->data_mode = FLB_DATA_MODE_CHUNK;
    }
    else {
        ctx->data_mode = FLB_DATA_MODE_SINGLE_RECORD;
    }

    return 0;
}


/**
