+/*
+ * Emit a group header record that preserves the hierarchical context of the
+ * OTLP payload for a given resource-scope combination.
+ *
+ * The group header carries:
+ *
+ *  - metadata : a map with 'schema' (always 'otlp'), 'resource_id' and
+ *               'scope_id' keys.
+ *  - body     : a map with 'resource' and 'scope' maps whose attributes are
+ *               converted from the OTLP key-value list representation into a
+ *               regular msgpack map.
+ */
+static int process_json_payload_group_header(
+        struct flb_opentelemetry *ctx,
+        struct flb_log_event_encoder *encoder,
+        msgpack_object *resource_object,
+        msgpack_object *scope_object,
+        int resource_logs_index,
+        int scope_logs_index)
+{
+    msgpack_object_map *resource_entry;
+    msgpack_object_map *scope_entry;
+    msgpack_object     *resource_attributes;
+    msgpack_object     *scope_attributes;
+    msgpack_object     *scope_name;
+    msgpack_object     *scope_version;
+    int                 entry_index;
+    int                 result;
+
+    resource_attributes = NULL;
+    scope_attributes = NULL;
+    scope_name = NULL;
+    scope_version = NULL;
+
+    /* Locate the resource attributes (OTLP key-value list) */
+    if (resource_object != NULL && resource_object->type == MSGPACK_OBJECT_MAP) {
+        resource_entry = &resource_object->via.map;
+
+        entry_index = find_map_entry_by_key(resource_entry, "attributes", 0, FLB_TRUE);
+        if (entry_index >= 0 &&
+            resource_entry->ptr[entry_index].val.type == MSGPACK_OBJECT_ARRAY) {
+            resource_attributes = &resource_entry->ptr[entry_index].val;
+        }
+    }
+
+    /* Locate the scope name, version and attributes */
+    if (scope_object != NULL && scope_object->type == MSGPACK_OBJECT_MAP) {
+        scope_entry = &scope_object->via.map;
+
+        entry_index = find_map_entry_by_key(scope_entry, "name", 0, FLB_TRUE);
+        if (entry_index >= 0 &&
+            scope_entry->ptr[entry_index].val.type == MSGPACK_OBJECT_STR) {
+            scope_name = &scope_entry->ptr[entry_index].val;
+        }
+
+        entry_index = find_map_entry_by_key(scope_entry, "version", 0, FLB_TRUE);
+        if (entry_index >= 0 &&
+            scope_entry->ptr[entry_index].val.type == MSGPACK_OBJECT_STR) {
+            scope_version = &scope_entry->ptr[entry_index].val;
+        }
+
+        entry_index = find_map_entry_by_key(scope_entry, "attributes", 0, FLB_TRUE);
+        if (entry_index >= 0 &&
+            scope_entry->ptr[entry_index].val.type == MSGPACK_OBJECT_ARRAY) {
+            scope_attributes = &scope_entry->ptr[entry_index].val;
+        }
+    }
+
+    result = flb_log_event_encoder_group_init(encoder);
+
+    /* Group header metadata */
+    if (result == FLB_EVENT_ENCODER_SUCCESS) {
+        result = flb_log_event_encoder_append_metadata_values(
+                    encoder,
+                    FLB_LOG_EVENT_CSTRING_VALUE("schema"),
+                    FLB_LOG_EVENT_CSTRING_VALUE("otlp"),
+                    FLB_LOG_EVENT_CSTRING_VALUE("resource_id"),
+                    FLB_LOG_EVENT_INT64_VALUE(resource_logs_index),
+                    FLB_LOG_EVENT_CSTRING_VALUE("scope_id"),
+                    FLB_LOG_EVENT_INT64_VALUE(scope_logs_index));

